 async function reviewChanges(path?:string){showOutput=true;consoleTab='changes';const chosen=path||task?.changes?.find(change=>change.after!==null)?.path||task?.target||'';if(task?.state==='completed'&&chosen){if(workspace?.files.some(file=>file.name===chosen)){if(chosen!==fileName)await openFile(chosen);}else{keep();fileName=chosen;fileContent='';if(!tabs.includes(chosen))tabs=[...tabs,chosen];}reviewPath=chosen;reviewing=true;preview=false;}else reviewing=false;}
 async function acceptChanges(){if(!workspace||task?.state!=='completed')return;const accepted=task,current=workspace;try{if(fileName&&!isAsset&&(accepted.changes?.some(change=>change.path===fileName&&change.after!==null)||(!accepted.changes?.length&&accepted.target===fileName))){const name=fileName;const fresh=await API.read(current.workspace_id,name);if(workspace?.workspace_id!==current.workspace_id||task!==accepted||fileName!==name)return;const state=acceptedEditorContent({reviewing,draft:fileContent,saved:saved[name],disk:fresh.content});fileContent=state.content;drafts[name]=state.content;saved[name]=state.baseline;revisions[name]=fresh.sha256;searchIndex[name]=fresh.content;}}catch(error){notice='Could not load the accepted file. Review is kept: '+String(error);return;}acceptedTaskId=task.task_id;localStorage.setItem('sovereign-accepted-task-'+workspace.workspace_id,acceptedTaskId);const removed=task.changes?.filter(change=>change.after===null).map(change=>change.path)||[];tabs=tabs.filter(name=>!removed.includes(name));if(removed.includes(fileName)){fileName='';fileContent='';if(tabs.length)void openFile(tabs[tabs.length-1]);}task=null;reviewing=false;reviewPath='';showChangeSummary=false;consoleTab='terminal';notice='Changes accepted. Edits are kept; the review baseline and highlights are cleared.';}
