 function choosePalette(item:string){paletteOpen=false;if(paletteMode==='files'){void openFile(item);return;}switch(item){case 'New file':showExplorer=true;newFileIn('');break;case 'New folder':showExplorer=true;newFolderIn('');break;case 'Save file':void saveFile();break;case 'Save all files':void saveAll();break;case 'Run file':void runFile();break;case 'Go to line':showPalette('line');break;case 'Reopen closed editor':reopenTab();break;case 'Close editor':if(fileName)closeTab(fileName);break;case 'Close all editors':requestClose(tabs);break;case 'Toggle Explorer':showExplorer=!showExplorer;break;case 'Search project':searchFiles();break;case 'Toggle Terminal':showOutput=!showOutput;break;case 'Focus terminal':chooseMenu('terminal');break;case 'Toggle Assistant':showAssistant=!showAssistant;break;case 'Show Problems':consoleTab='problems';showOutput=true;break;case 'Review changes':void reviewChanges();break;case 'Toggle Auto Save':chooseMenu('auto-save');break;case 'Keyboard shortcuts':shortcutsOpen=true;break;case 'Find in file':editorAction('actions.find');break;case 'Replace in file':editorAction('editor.action.startFindReplaceAction');break;case 'Toggle line comment':editorAction('editor.action.commentLine');break;case 'Format document':if(formatSupported)editorAction('editor.action.formatDocument');else notice='Formatting is available for JavaScript, TypeScript, JSON, HTML and CSS files.';break;case 'Toggle Word Wrap':editorAction('toggle-word-wrap');break;case 'Toggle Minimap':editorAction('toggle-minimap');break;case 'Open project in VS Code':void openInVSCode();break;}}
