 function nudgeSide(side:'explorer'|'assistant',event:KeyboardEvent){if(event.key!=='ArrowLeft'&&event.key!=='ArrowRight')return;event.preventDefault();const change=(event.key==='ArrowRight'?20:-20)*(side==='explorer'?1:-1);if(side==='explorer'){explorerWidth=Math.max(170,Math.min(600,explorerWidth+change));localStorage.setItem('sovereign-explorer-width',String(explorerWidth));}else{assistantWidth=Math.max(170,Math.min(600,assistantWidth+change));localStorage.setItem('sovereign-assistant-width',String(assistantWidth));}}
 function keyboard(event:KeyboardEvent){if(!ideElement?.getClientRects().length)return;const key=event.key.toLowerCase();if(event.key==='Escape'){if(menuOpen){event.preventDefault();menuOpen=null;return;}if(shortcutsOpen){event.preventDefault();shortcutsOpen=false;return;}if(paletteOpen){event.preventDefault();paletteOpen=false;return;}if(fileDialog){event.preventDefault();fileDialog=null;return;}if(fileMenu){event.preventDefault();fileMenu=null;return;}if(tabMenu){event.preventDefault();tabMenu=null;return;}if(closeRequest){event.preventDefault();if(!closeSaving)closeRequest=null;return;}if(focusMode){event.preventDefault();void exitFocus();return;}}const treeItem=(event.target as HTMLElement)?.closest<HTMLElement>('.explorer-tree-area button[title], .explorer-tree-area summary[title]');const treePath=treeItem?.getAttribute('title')||'',treeKind=treeItem?.tagName==='SUMMARY'?'folder':'file';if(treePath&&event.key==='F2'){event.preventDefault();beginFileDialog('rename',treePath,treeKind);return;}if(treePath&&event.key==='Delete'){event.preventDefault();beginFileDialog('delete',treePath,treeKind);return;}if(treePath&&(event.ctrlKey||event.metaKey)&&['c','x','v'].includes(key)){event.preventDefault();if(key==='c')setFileClipboard(treePath,'copy',treeKind);else if(key==='x')setFileClipboard(treePath,'cut',treeKind);else void pasteFile(treeKind==='folder'?treePath:treePath.includes('/')?treePath.slice(0,treePath.lastIndexOf('/')):'');return;}if(paletteOpen)return;if(event.key==='F1'){event.preventDefault();showPalette('commands');return;}if(event.key==='F5'&&!event.ctrlKey){event.preventDefault();void runFile();return;}if(!event.ctrlKey&&!event.metaKey)return;if(key==='p'){event.preventDefault();showPalette(event.shiftKey?'commands':'files');}else if(key==='`'){event.preventDefault();showOutput=true;consoleTab='terminal';setTimeout(()=>document.querySelector<HTMLInputElement>('.ide .terminal-input input')?.focus(),0);}else if(key==='b'&&!event.altKey){event.preventDefault();showExplorer=!showExplorer;}else if(key==='j'){event.preventDefault();showOutput=!showOutput;}else if(key==='b'&&event.altKey){event.preventDefault();showAssistant=!showAssistant;}else if(key==='e'&&event.shiftKey){event.preventDefault();showExplorer=true;sidebarView='explorer';}else if(key==='f'&&event.shiftKey){event.preventDefault();searchFiles();}else if(key==='n'&&!event.shiftKey){event.preventDefault();showExplorer=true;newFileIn('');}else if(key==='g'){event.preventDefault();showPalette('line');}else if(key==='t'&&event.shiftKey){event.preventDefault();reopenTab();}else if(key==='w'&&fileName){event.preventDefault();closeTab(fileName);}else if(key==='tab'&&tabs.length>1){event.preventDefault();const index=tabs.indexOf(fileName);void openFile(tabs[(index+(event.shiftKey?-1:1)+tabs.length)%tabs.length]);}}
