 async function newFolder(){if(!newName.trim())return;try{const current=await ensureWorkspace();const result=await API.fileOperation(current.workspace_id,'mkdir',newName.trim());workspace=result.workspace;notice=`Created folder ${newName.trim()}`;creatingFolder=false;newName='';}catch(e){notice=String(e);}}
 function setFileClipboard(path:string,mode:'copy'|'cut',kind:'file'|'folder'='file'){fileClipboard={path,mode,kind};fileMenu=null;notice=`${mode==='copy'?'Copied':'Cut'} ${path}. Choose Paste in a folder or Explorer.`;}
 function beginFileDialog(action:'rename'|'delete',path:string,kind:'file'|'folder'='file'){fileMenu=null;renameValue=path.split('/').pop()||'';fileDialog={action,path,kind};setTimeout(()=>document.querySelector<HTMLInputElement>('.ide [aria-label="New file name"]')?.focus(),0);}
 function updateFileState(action:'copy'|'move'|'delete',source:string,destination?:string){
  keep();const affected=(name:string)=>name===source||name.startsWith(source+'/');const mapped=(name:string)=>destination!+name.slice(source.length);if(action==='move'&&destination){if(terminalCwd&&(terminalCwd===source||terminalCwd.startsWith(source+'/')))terminalCwd=mapped(terminalCwd);tabs=tabs.map(n=>affected(n)?mapped(n):n);if(affected(fileName))fileName=mapped(fileName);for(const state of [drafts,saved,searchIndex,revisions])for(const name of Object.keys(state)){if(affected(name)){state[mapped(name)]=state[name];delete state[name];}}}
  if(action==='delete'){if(terminalCwd&&(terminalCwd===source||terminalCwd.startsWith(source+'/')))terminalCwd='';tabs=tabs.filter(n=>!affected(n));for(const state of [drafts,saved,searchIndex,revisions])for(const name of Object.keys(state))if(affected(name))delete state[name];if(affected(fileName)){fileName='';fileContent='';if(tabs.length)void openFile(tabs[tabs.length-1]);}}
 }
 async function performFileOperation(action:'copy'|'move'|'delete',source:string,destination?:string){if(!workspace||busy)return false;try{const wasFolder=workspace.folders?.includes(source)||false;const result=await API.fileOperation(workspace.workspace_id,action,source,destination);updateFileState(action,source,destination);workspace=result.workspace;notice=`${action==='copy'?'Copied':action==='move'?'Moved':'Deleted'} ${source}${destination?' → '+destination:''}`;if(action==='copy'&&destination&&!wasFolder)void openFile(destination);return true;}catch(e){notice=String(e);return false;}finally{fileMenu=null;fileDialog=null;}}
 function uniqueCopyName(source:string,folder:string){const base=source.split('/').pop()||source;const dot=base.lastIndexOf('.');const stem=dot>0?base.slice(0,dot):base,ext=dot>0?base.slice(dot):'';let candidate='',index=1;do{candidate=(folder?folder+'/':'')+stem+' copy'+(index>1?' '+index:'')+ext;index++;}while(workspace?.files.some(f=>f.name===candidate)||workspace?.folders?.includes(candidate));return candidate;}
 async function pasteFile(folder:string){const clip=fileClipboard;if(!clip||!workspace)return;const name=clip.path.split('/').pop()||clip.path;const destination=clip.mode==='copy'?uniqueCopyName(clip.path,folder):(folder?folder+'/':'')+name;if(destination===clip.path){notice='Item is already in that folder.';fileMenu=null;return;}const completed=await performFileOperation(clip.mode==='copy'?'copy':'move',clip.path,destination);if(completed&&clip.mode==='cut')fileClipboard=null;}
 async function copyPath(path:string){try{await navigator.clipboard.writeText(path);notice=`Copied path: ${path}`;}catch{notice='Clipboard access is unavailable.';}fileMenu=null;}
 async function saveAll(){if(!workspace)return;keep();try{for(const [name,value] of Object.entries(drafts)){if(value!==saved[name]){const written=await persistDraft(workspace.workspace_id,name,value,revisions[name]);revisions[name]=written.sha256;saved[name]=value;searchIndex[name]=value;}}notice='All open files saved.';}catch(e){notice=String(e);}}
 async function confirmFileDialog(){if(!fileDialog)return;const {action,path}=fileDialog;if(action==='delete'){await performFileOperation('delete',path);return;}if(action==='save-as'){const destination=renameValue.trim();if(!workspace||!destination||workspace.files.some(f=>f.name===destination)){notice='Choose a new path that does not exist.';return;}try{if(assetFiles[path]){await API.fileOperation(workspace.workspace_id,'copy',path,destination);workspace=await API.get(workspace.workspace_id);fileDialog=null;await openFile(destination);notice='Copied asset to '+destination;return;}const written=await API.write(workspace.workspace_id,destination,fileContent,'');revisions[destination]=written.sha256;workspace=await API.get(workspace.workspace_id);saved[destination]=fileContent;drafts[destination]=fileContent;fileDialog=null;await openFile(destination);notice='Saved as '+destination;}catch(e){notice=String(e);}return;}const parent=path.includes('/')?path.slice(0,path.lastIndexOf('/')+1):'';const destination=parent+renameValue.trim();if(destination===path){fileDialog=null;return;}await performFileOperation('move',path,destination);}
 async function enterFocus(){focusMode=true;document.body.classList.add('sovereign-code-focus');try{await ideElement.requestFullscreen();}catch{/* The in-app browser may deny fullscreen; the viewport-sized IDE remains available. */}}
 async function exitFocus(){focusMode=false;document.body.classList.remove('sovereign-code-focus');if(document.fullscreenElement===ideElement)await document.exitFullscreen().catch(()=>undefined);}
 function fullscreenChanged(){if(focusMode&&document.fullscreenElement!==ideElement){focusMode=false;document.body.classList.remove('sovereign-code-focus');}}
 onMount(()=>{if(window.innerWidth<=800){showExplorer=false;showAssistant=false;}autoSave=localStorage.getItem('sovereign-code-auto-save')==='1';terminalHeight=Math.max(130,Math.min(520,Number(localStorage.getItem('sovereign-terminal-height'))||230));explorerWidth=Math.max(170,Math.min(600,Number(localStorage.getItem('sovereign-explorer-width'))||260));assistantWidth=Math.max(170,Math.min(600,Number(localStorage.getItem('sovereign-assistant-width'))||320));const openRequested=(event:Event)=>{const detail=(event as CustomEvent<{tab?:string;taskId?:string}>).detail;if(detail?.tab!=='code'||busy)return;void (async()=>{const id=localStorage.getItem('sovereign-active-workspace');if(id&&id!==workspace?.workspace_id)await openWorkspace(id);else if(workspace&&fileName){if(dirty){notice='Save or discard your unsaved editor changes before reloading the agent edit.';return;}else{const file=await API.read(workspace.workspace_id,fileName);fileContent=file.content;drafts[fileName]=file.content;saved[fileName]=file.content;revisions[fileName]=file.sha256;}}if(id&&detail.taskId){task=await request(`/coding/workspaces/${id}/tasks/${detail.taskId}`);if(task?.target){const fresh=await API.read(id,task.target);drafts[task.target]=fresh.content;saved[task.target]=fresh.content;revisions[task.target]=fresh.sha256;if(fileName!==task.target)await openFile(task.target);else fileContent=fresh.content;}reviewChanges();}})().catch(e=>notice=String(e));};window.addEventListener('sovereign-open-workspace',openRequested);document.addEventListener('fullscreenchange',fullscreenChanged);void (async()=>{try{await refresh();let pending:{job_id:string;workspace_id:string;target:string}|null=null;try{pending=JSON.parse(localStorage.getItem('sovereign-code-job')||'null');}catch{localStorage.removeItem('sovereign-code-job');}const id=pending?.workspace_id||localStorage.getItem('sovereign-active-workspace');if(id&&workspaces.some(w=>w.workspace_id===id)){await openWorkspace(id);if(pending?.target)await openFile(pending.target);}if(pending?.job_id){jobId=pending.job_id;busy=true;void pollJob();}}catch(e){notice=String(e);}})();void refreshRuntime();return ()=>{clearTimeout(pollTimer);window.removeEventListener('sovereign-open-workspace',openRequested);document.removeEventListener('fullscreenchange',fullscreenChanged);document.body.classList.remove('sovereign-code-focus');if(document.fullscreenElement===ideElement)void document.exitFullscreen();};});
 async function refresh(){workspaces=await API.list();}
 async function refreshExplorer(){await refresh();const current=workspace;if(!current||busy)return;keep();try{const fresh=await API.get(current.workspace_id);if(workspace?.workspace_id!==current.workspace_id)return;workspace=fresh;const reads=await Promise.allSettled(tabs.filter(name=>fresh.files.some(file=>file.name===name)&&drafts[name]===saved[name]).map(name=>API.read(current.workspace_id,name)));if(workspace?.workspace_id!==current.workspace_id)return;for(const result of reads){if(result.status==='fulfilled'){const file=result.value;if(drafts[file.name]!==saved[file.name]||(file.name===fileName&&fileContent!==saved[file.name]))continue;if(file.editable===false){assetFiles[file.name]={bytes:file.bytes||0,binary:!!file.binary};delete drafts[file.name];delete saved[file.name];continue;}delete assetFiles[file.name];drafts[file.name]=file.content;saved[file.name]=file.content;revisions[file.name]=file.sha256;if(fileName===file.name)fileContent=file.content;}}const missing=tabs.filter(name=>!fresh.files.some(file=>file.name===name)&&drafts[name]===saved[name]);if(missing.length)finishClose(missing);indexedWorkspace='';searchIndex={};if(sidebarView==='search')void loadSearchIndex();notice=Object.keys(drafts).some(name=>drafts[name]!==saved[name])?'Workspace refreshed. Unsaved editor drafts were preserved.':'Workspace refreshed from the project files.';}catch(error){notice=String(error);}}
 async function refreshRuntime(){try{runtime=await WorkbenchService.info();}catch(e){notice=String(e);}}
 function saveCodingTurns(){if(workspace)localStorage.setItem('sovereign-code-history-'+workspace.workspace_id,JSON.stringify(codingTurns.slice(-30)));}
 function loadCodingTurns(id:string){try{const history=JSON.parse(localStorage.getItem('sovereign-code-history-'+id)||'[]');codingTurns=Array.isArray(history)?history:[];}catch{codingTurns=[];}}
 async function openCodingTurn(turn:CodingTurn){if(!workspace||busy)return;try{const result=turn.taskId?await request(`/coding/workspaces/${workspace.workspace_id}/tasks/${turn.taskId}`):(await request('/coding/jobs/'+turn.jobId)).result;if(result){task=result;showOutput=true;consoleTab='changes';}else notice='This task has no saved result to review.';}catch(e){notice=String(e);}}
 function keep(){if(fileName&&!isAsset)drafts[fileName]=fileContent;}
 async function openWorkspace(id:string){if(busy)return;keep();if(Object.keys(drafts).some(n=>drafts[n]!==saved[n])){notice='Save your changes before switching projects.';return;}try{workspace=id?await API.get(id):null;fileClipboard=null;fileMenu=null;fileDialog=null;localStorage.setItem('sovereign-active-workspace',id);acceptedTaskId=id?localStorage.getItem('sovereign-accepted-task-'+id)||'':'';terminalCwd='';tabs=[];closedTabs=[];drafts={};saved={};revisions={};searchIndex={};indexedWorkspace='';searchQuery='';fileName='';fileContent='';assetFiles={};clearAssetUrl();output='';task=null;reviewing=false;saveConflict=null;conflictReview=false;if(workspace)loadCodingTurns(workspace.workspace_id);else codingTurns=[];if(workspace?.files.length)await openFile(workspace.files[0].name);if(sidebarView==='search')void loadSearchIndex();}catch(e){notice=String(e);}}
 async function ensureWorkspace(name='Untitled project'){if(!workspace){workspace=await API.create(name.slice(0,80));loadCodingTurns(workspace.workspace_id);await refresh();}localStorage.setItem('sovereign-active-workspace',workspace.workspace_id);return workspace;}
 async function openFile(name:string){if(!workspace)return;keep();const current=workspace;try{clearAssetUrl();const file=await API.read(current.workspace_id,name);if(workspace?.workspace_id!==current.workspace_id)return;if(file.editable===false){assetFiles[name]={bytes:file.bytes||0,binary:!!file.binary};delete drafts[name];delete saved[name];}else{delete assetFiles[name];if(!(name in drafts)){drafts[name]=file.content;saved[name]=file.content;revisions[name]=file.sha256;}}searchLine=0;fileName=name;fileContent=drafts[name]||'';reviewing=false;if(!tabs.includes(name))tabs=[...tabs,name];preview=/\.svg$/i.test(name);conflictReview=false;if(assetFiles[name]){const blob=await API.asset(current.workspace_id,name);const types:Record<string,string>={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',bmp:'image/bmp',ico:'image/x-icon',avif:'image/avif',svg:'image/svg+xml'};const mime=types[name.split('.').pop()?.toLowerCase()||''];if(fileName===name&&workspace?.workspace_id===current.workspace_id)assetUrl=URL.createObjectURL(mime?new Blob([blob],{type:mime}):blob);}}catch(e){notice=String(e);}}

 async function persistDraft(id:string,name:string,content:string,revision?:string){try{return await API.write(id,name,content,revision);}catch(error){if(error instanceof ApiError&&error.status===409){const disk=await API.read(id,name);saveConflict={name,content:disk.content,sha256:disk.sha256};conflictReview=false;notice='File changed on disk. Your edits are kept; compare the versions before saving.';}throw error;}}
 async function compareConflict(){if(!saveConflict)return;await openFile(saveConflict.name);preview=false;reviewing=false;conflictReview=true;}
 async function resolveConflict(useDisk:boolean){const conflict=saveConflict;if(!conflict||!workspace)return;if(useDisk){drafts[conflict.name]=conflict.content;saved[conflict.name]=conflict.content;revisions[conflict.name]=conflict.sha256;searchIndex[conflict.name]=conflict.content;if(fileName===conflict.name)fileContent=conflict.content;saveConflict=null;conflictReview=false;notice='Loaded the disk version; unsaved edits for this file were discarded.';}else{keep();try{const written=await persistDraft(workspace.workspace_id,conflict.name,drafts[conflict.name],conflict.sha256);saved[conflict.name]=drafts[conflict.name];searchIndex[conflict.name]=drafts[conflict.name];revisions[conflict.name]=written.sha256;saveConflict=null;conflictReview=false;notice='Saved your version after comparison.';}catch(error){notice=String(error);}}}
 async function saveFile(contentOverride?:string){if(!fileName||isAsset)return false;const name=fileName,content=contentOverride??fileContent,revision=revisions[name];fileContent=content;const w=await ensureWorkspace();try{const written=await persistDraft(w.workspace_id,name,content,revision);if(workspace?.workspace_id!==w.workspace_id)return true;revisions[name]=written.sha256;saved[name]=content;drafts[name]=fileName===name?fileContent:drafts[name]??content;searchIndex[name]=content;workspace=await API.get(w.workspace_id);notice='Saved '+name;return true;}catch(e){notice=String(e);return false;}}

 async function newFile(){if(!newName.trim())return;try{const w=await ensureWorkspace();if(w.files.some(f=>f.name===newName.trim()))throw Error('That file already exists. Open it from Explorer.');await API.write(w.workspace_id,newName.trim(),'','');workspace=await API.get(w.workspace_id);await openFile(newName.trim());newName='';creating=false;}catch(e){notice=String(e);}}
 async function importFiles(event:Event){const input=event.currentTarget as HTMLInputElement;const files=Array.from(input.files||[]);if(!files.length)return;keep();if(Object.keys(drafts).some(n=>drafts[n]!==saved[n])){notice='Save your changes before importing files.';input.value='';return;}busy=true;let imported=0;const skipped:string[]=[];try{const folder=files[0].webkitRelativePath?.split('/')[0];if(folder&&workspace){workspace=await API.create(folder.slice(0,80));tabs=[];drafts={};saved={};assetFiles={};clearAssetUrl();fileName='';fileContent='';await refresh();}const w=await ensureWorkspace(folder||'Imported project');for(const file of files){const name=file.webkitRelativePath?file.webkitRelativePath.split('/').slice(1).join('/'):file.name;if(/(^|\/)(node_modules|\.git|\.venv|venv|dist|build|target|__pycache__)(\/|$)/.test(name)){skipped.push(name+' (generated folder)');continue;}if(file.size>20*1024*1024){skipped.push(name+' (over 20 MiB)');continue;}try{await API.importFile(w.workspace_id,name,file);imported++;}catch(e){skipped.push(name+': '+String(e));}}workspace=await API.get(w.workspace_id);await refresh();indexedWorkspace='';notice=`Imported ${imported} files. ${skipped.length} skipped.`;output=skipped.length?'Import details:\n'+skipped.join('\n'):'All selected files imported.';if(skipped.length){showOutput=true;consoleTab='terminal';}}catch(e){notice=String(e);}finally{busy=false;input.value='';if(workspace?.files.length&&!fileName)await openFile(workspace.files[0].name);}}

 async function refreshApplicationWorkspace(id:string){
  keep();const prior=workspace?.workspace_id;if(prior&&prior!==id&&Object.keys(drafts).some(name=>drafts[name]!==saved[name])){notice='Task finished in another project. Save your current drafts before switching projects.';return false;}
  const fresh=await API.get(id);if(prior&&prior!==id){tabs=[];drafts={};saved={};revisions={};assetFiles={};fileName='';fileContent='';clearAssetUrl();}
  workspace=fresh;localStorage.setItem('sovereign-active-workspace',id);await refresh();
  const clean=tabs.filter(name=>drafts[name]===saved[name]);
  for(const name of clean){if(!fresh.files.some(file=>file.name===name)){finishClose([name]);continue;}const file=await API.read(id,name);if(drafts[name]!==saved[name])continue;if(file.editable===false){assetFiles[name]={bytes:file.bytes||0,binary:!!file.binary};delete drafts[name];delete saved[name];}else{delete assetFiles[name];drafts[name]=file.content;saved[name]=file.content;revisions[name]=file.sha256;if(fileName===name)fileContent=file.content;}}
  indexedWorkspace='';searchIndex={};if(sidebarView==='search')void loadSearchIndex();return true;
 }
 async function pollJob(){try{const job=await request('/coding/jobs/'+jobId);const routeTurn=codingTurns.find(item=>item.jobId===jobId);if(routeTurn&&(job.routing||job.result?.routing)){routeTurn.routing=job.result?.routing||job.routing;codingTurns=[...codingTurns];saveCodingTurns();}jobKind=job.kind;output=job.output||'';stage=job.stage;elapsed=job.elapsed;timeline=job.events||[];if(job.state==='running'){notice=stage;activity(true,stage);pollTimer=setTimeout(()=>void pollJob(),600);return;}localStorage.removeItem('sovereign-code-job');notice=job.error||`${job.stage} · ${job.elapsed}s`;if(job.kind==='agent'){const response=job.result;const operations=Array.isArray(response?.result?.operations)?response.result.operations:[];const application=response?.plan?.action==='application_tools';const edited=[...operations].reverse().find((operation:any)=>operation.tool==='file_edit'&&operation.result?.state==='completed')?.result;const editResult=response?.plan?.action==='edit_code'?response.result:edited;if(operations.some((operation:any)=>typeof operation.tool==='string'&&operation.tool.startsWith('document_')))void knowledgeContext.refresh().catch(error=>notice='Task finished, but the Knowledge list could not refresh: '+String(error));const applicationSynced=application&&response?.workspace_id?await refreshApplicationWorkspace(response.workspace_id):true;const turn=codingTurns.find(item=>item.jobId===jobId);if(turn){turn.state=job.state==='cancelled'?'stopped':response?.result?.state==='completed'?'completed':job.error?'failed':'answered';turn.answer=response?.answer||job.error||'';turn.taskId=editResult?.task_id;codingTurns=[...codingTurns];saveCodingTurns();}if(response?.routing)window.dispatchEvent(new CustomEvent('sovereign-route',{detail:{task:response.plan?.action||'Code',...response.routing}}));if(editResult&&(!application||applicationSynced)&&response.workspace_id){workspace=await API.get(response.workspace_id);localStorage.setItem('sovereign-active-workspace',response.workspace_id);await refresh();}if(editResult&&(!application||applicationSynced)){keep();task=editResult;for(const change of task?.changes||[]){if(change.after!==null&&workspace?.files.some(file=>file.name===change.path)&&drafts[change.path]===saved[change.path]){const freshFile=await API.read(workspace.workspace_id,change.path);const content=freshFile.content;revisions[change.path]=freshFile.sha256;drafts[change.path]=content;saved[change.path]=content;if(fileName===change.path)fileContent=content;}else if(change.after===null&&drafts[change.path]===saved[change.path]){tabs=tabs.filter(name=>name!==change.path);delete drafts[change.path];delete saved[change.path];if(fileName===change.path){fileName='';fileContent='';}}}showOutput=true;consoleTab='changes';if(task?.state==='completed'&&task.task_id!==acceptedTaskId&&(!task.target||drafts[task.target]===saved[task.target]))await reviewChanges();}else showOutput=false;busy=false;jobKind=null;activity(false,stage);return;}if(job.result?.stderr&&!output.includes(job.result.stderr))output+='\n'+job.result.stderr;if(job.kind==='terminal'&&job.state==='completed'&&(job.result?.changed_files?.length||job.result?.deleted_files?.length)){const id=job.result.workspace_id||workspace?.workspace_id;if(id){try{await refreshApplicationWorkspace(id);}catch(error){notice='Command finished, but the workspace could not refresh: '+String(error);}}}if(job.kind==='edit'){const turn=codingTurns.find(item=>item.jobId===jobId);if(turn){turn.state=job.result?.state==='completed'?'completed':job.state==='cancelled'?'stopped':'failed';turn.taskId=job.result?.task_id;saveCodingTurns();}if(job.result?.state==='answered'){if(turn){turn.state='answered';turn.answer=job.result.answer;saveCodingTurns();}if(job.result.routing)window.dispatchEvent(new CustomEvent('sovereign-route',{detail:{task:'Code answer',...job.result.routing}}));showOutput=false;}else if(job.result){task=job.result;if(task?.routing)window.dispatchEvent(new CustomEvent('sovereign-route',{detail:{task:'Coding',...task.routing}}));if(workspace){workspace=await API.get(workspace.workspace_id);for(const change of task?.changes||[]){if(change.after!==null&&workspace.files.some(file=>file.name===change.path)&&drafts[change.path]===saved[change.path]){const freshFile=await API.read(workspace.workspace_id,change.path);const content=freshFile.content;revisions[change.path]=freshFile.sha256;drafts[change.path]=content;saved[change.path]=content;if(fileName===change.path)fileContent=content;}if(change.after===null&&!workspace.files.some(file=>file.name===change.path)){tabs=tabs.filter(name=>name!==change.path);delete drafts[change.path];delete saved[change.path];if(fileName===change.path){fileName='';fileContent='';}}}}showOutput=true;consoleTab='changes';if(task?.state==='completed'&&task.task_id!==acceptedTaskId)await reviewChanges();}}if(job.error)output+='\n'+job.error;busy=false;jobKind=null;activity(false,stage);}catch(e){busy=false;jobKind=null;notice=String(e);const turn=codingTurns.find(item=>item.jobId===jobId);if(turn){turn.state='failed';saveCodingTurns();}localStorage.removeItem('sovereign-code-job');activity(false,'');}}
 async function startJob(kind:'run'|'edit'|'terminal'){if(busy)return;let pendingId='';try{const w=await ensureWorkspace();if(fileName&&!await saveFile())return;const instruction=prompt.trim(),target=fileName;if(kind==='edit'){stickToLatest=true;pendingId=crypto.randomUUID();codingTurns=[...codingTurns,{jobId:pendingId,instruction,state:'running',target,at:Date.now()}];saveCodingTurns();prompt='';task=null;reviewing=false;}busy=true;jobKind=kind;timeline=[];elapsed=0;stage=kind==='edit'?'Reading project structure':'Starting program';notice=stage;activity(true,stage);output='';consoleTab='terminal';const job=await request(`/coding/workspaces/${w.workspace_id}/jobs`,{kind,target,instruction,command:terminalCommand,cwd:terminalCwd});jobId=job.job_id;activity(true,stage);localStorage.setItem('sovereign-code-job',JSON.stringify({job_id:jobId,workspace_id:w.workspace_id,target,instruction}));if(pendingId){const turn=codingTurns.find(item=>item.jobId===pendingId);if(turn){turn.jobId=jobId;codingTurns=[...codingTurns];saveCodingTurns();}}if(kind==='terminal')terminalCommand='';void pollJob();}catch(e){busy=false;jobKind=null;notice=String(e);output=String(e);if(pendingId){const turn=codingTurns.find(item=>item.jobId===pendingId);if(turn){turn.state='failed';turn.answer=String(e);codingTurns=[...codingTurns];saveCodingTurns();}}activity(false,'');}}
 async function runFile(){if(!fileName)return;await startJob('run');showOutput=true;consoleTab='terminal';requestAnimationFrame(()=>document.querySelector<HTMLInputElement>('.ide .terminal-input input')?.focus());}
 function newCodingChat(){if(busy)return;codingTurns=[];task=null;prompt='';reviewing=false;notice='New conversation. Workspace files are unchanged.';saveCodingTurns();}
 async function askAI(){if(!prompt.trim()||busy)return;const instruction=prompt.trim();const error=agentGoalError(instruction);if(error){notice=error;return;}const requestAdmission=createJobAdmission(id=>request('/coding/jobs/'+id+'/stop',{}));admission=requestAdmission;jobId='';const selectedWorkspace=workspace?.workspace_id||null;const target=fileName;const pendingId=crypto.randomUUID();stickToLatest=true;codingTurns=[...codingTurns,{jobId:pendingId,instruction,state:'running',target,at:Date.now()}];prompt='';task=null;reviewing=false;busy=true;jobKind='agent';timeline=[];elapsed=0;stage='Understanding the request';notice=stage;activity(true,stage);saveCodingTurns();try{const history=agentConversationHistory(codingTurns);const job=await request('/agent/jobs',{goal:instruction,workspace_id:selectedWorkspace,document_ids:[],history});jobId=job.job_id;const turn=codingTurns.find(item=>item.jobId===pendingId);if(turn)turn.jobId=jobId;await requestAdmission.admit(jobId).catch(error=>notice=String(error));codingTurns=[...codingTurns];saveCodingTurns();localStorage.setItem('sovereign-code-job',JSON.stringify({job_id:jobId,workspace_id:selectedWorkspace||'',target,instruction}));void pollJob();}catch(e){busy=false;jobKind=null;notice=String(e);const turn=codingTurns.find(item=>item.jobId===pendingId);if(turn){turn.state='failed';turn.answer=String(e);}codingTurns=[...codingTurns];saveCodingTurns();activity(false,'');}}
 async function stopJob(){if(!busy)return;notice='Stopping after the current step…';try{if(jobKind==='agent'&&admission)await admission.requestStop();else if(jobId)await request('/coding/jobs/'+jobId+'/stop',{});}catch(e){notice=String(e);}}
 async function openInVSCode(){if(!workspace){notice='Open a workspace before opening VS Code.';return;}menuOpen=null;try{const result=await API.openVSCode(workspace.workspace_id);notice='Opened this project in VS Code: '+result.path;}catch(error){notice=String(error);}}
 async function revealProject(){if(!workspace)return;try{const result=await API.reveal(workspace.workspace_id);notice='Opened project folder: '+result.path;}catch(error){notice=String(error);}}
 function changeDirectory(command:string){const match=/^cd(?:\s+(.*))?$/i.exec(command.trim());if(!match||!workspace)return false;if(match[1]&&/[;&|]/.test(match[1]))return false;let absoluteScope=false;let requested=(match[1]||'').trim().replace(/^(["'])(.*)\1$/,'$2').replace(/\\/g,'/');const host=(workspace.host_path||'').replace(/\\/g,'/');if(host&&(requested.toLowerCase()===host.toLowerCase()||requested.toLowerCase().startsWith(host.toLowerCase()+'/'))){requested=requested.slice(host.length).replace(/^\//,'');absoluteScope=true;}else if(/^[a-z]:\//i.test(requested)||requested.startsWith('/')){const docker='/output/project';if(requested===docker||requested.startsWith(docker+'/')){requested=requested.slice(docker.length).replace(/^\//,'');absoluteScope=true;}else{notice='Terminal commands are scoped to this project. Use its folders or open the project in File Explorer.';return true;}}const parts=match[1]&&!absoluteScope?terminalCwd.split('/').filter(Boolean):[];if(requested.startsWith('/'))parts.length=0;for(const part of requested.split('/')){if(!part||part==='.')continue;if(part==='..'){if(!parts.length){notice='Cannot change directory outside the project.';return true;}parts.pop();}else parts.push(part);}let destination=parts.join('/');const folders=new Set([...(workspace.folders||[]),...workspace.files.flatMap(file=>{const segments=file.name.split('/');return segments.slice(0,-1).map((_,index)=>segments.slice(0,index+1).join('/'));})]);if(destination&&!folders.has(destination)){notice='Project folder does not exist: '+destination;return true;}terminalCwd=destination;output+=(output?'\n':'')+'$ cd '+(destination||'.')+'\nDocker working directory: /output/project'+(destination?'/'+destination:'');terminalCommand='';notice='Terminal folder: '+(destination||'project root');return true;}
 async function submitTerminal(){if(!terminalCommand.trim())return;if(!busy&&/^(clear|cls)$/i.test(terminalCommand.trim())){output='';terminalCommand='';return;}const entered=terminalCommand;if(!busy&&changeDirectory(terminalCommand)){commandHistory=[...commandHistory,entered].slice(-50);historyPosition=commandHistory.length;return;}try{if(busy){if(jobKind==='edit'||jobKind==='agent'){notice='Terminal input is paused while the assistant works.';return;}if(consoleTab!=='terminal')consoleTab='terminal';const input=terminalCommand;await request('/coding/jobs/'+jobId+'/input',{text:input+'\n'});terminalCommand='';notice='Input sent to the running program';requestAnimationFrame(()=>document.querySelector<HTMLInputElement>('.ide .terminal-input input')?.focus());}else{commandHistory=[...commandHistory,terminalCommand].slice(-50);historyPosition=commandHistory.length;await startJob('terminal');requestAnimationFrame(()=>document.querySelector<HTMLInputElement>('.ide .terminal-input input')?.focus());}}catch(e){notice=String(e);}}
 function closeTab(name:string){requestClose([name]);}
 function requestClose(names:string[]){keep();tabMenu=null;const requested=[...names];if(requested.some(name=>drafts[name]!==saved[name])){closeRequest=requested;setTimeout(()=>document.querySelector<HTMLButtonElement>('.unsaved-dialog [data-cancel]')?.focus(),0);}else finishClose(requested);}
 function finishClose(names:string[]){keep();closedTabs=[...closedTabs,...names].slice(-30);tabs=tabs.filter(name=>!names.includes(name));for(const name of names){delete drafts[name];delete saved[name];delete revisions[name];}if(names.includes(fileName)){fileName='';fileContent='';if(tabs.length)void openFile(tabs[tabs.length-1]);}closeRequest=null;}
 async function confirmClose(save:boolean){if(!closeRequest||!workspace)return;closeSaving=true;const requested=[...closeRequest];try{if(save){keep();for(const name of requested){if(drafts[name]!==saved[name]){const written=await persistDraft(workspace.workspace_id,name,drafts[name],revisions[name]);revisions[name]=written.sha256;saved[name]=drafts[name];searchIndex[name]=drafts[name];}}}finishClose(requested);}catch(error){notice=String(error);closeRequest=null;}finally{closeSaving=false;}}
 function reopenTab(){const name=closedTabs.at(-1);if(!name)return;closedTabs=closedTabs.slice(0,-1);if(workspace?.files.some(file=>file.name===name))void openFile(name);}
 function showTabMenu(event:MouseEvent,name:string){event.preventDefault();tabMenu={name,x:Math.min(event.clientX,window.innerWidth-220),y:Math.min(event.clientY,window.innerHeight-260)};}

 const previewDocument=$derived(/\.html?$/i.test(fileName)?'<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; script-src \'unsafe-inline\'; img-src data:;">'+fileContent:'<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\';"><style>body{font:15px/1.7 system-ui;padding:32px;white-space:pre-wrap;background:#fff;color:#202127}</style>'+fileContent.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;'));
</script>
