  <nav class="ide-menubar" aria-label="Code menu">{#each ['file','edit','selection','view','go','run','terminal','help'] as menu}<div class="ide-menu"><button aria-expanded={menuOpen===menu} onclick={()=>menuOpen=menuOpen===menu?null:menu as typeof menuOpen}>{menu[0].toUpperCase()+menu.slice(1)}</button>{#if menuOpen===menu}<div class="ide-menu-pop" role="menu">{#if menu==='file'}<button onclick={()=>chooseMenu('new')}>New file <kbd>Ctrl+N</kbd></button><button onclick={()=>chooseMenu('folder')}>New folder</button><button onclick={()=>chooseMenu('open')}>Quick open <kbd>Ctrl+P</kbd></button><button onclick={()=>chooseMenu('import-files')}>Import files</button><button onclick={()=>chooseMenu('import-folder')}>Import folder</button><div class="file-menu-separator"></div><button onclick={()=>chooseMenu('save')} disabled={!fileName}>Save <kbd>Ctrl+S</kbd></button><button onclick={()=>chooseMenu('save-as')} disabled={!fileName}>Save as…</button><button onclick={()=>chooseMenu('save-all')} disabled={!workspace}>Save all</button><button onclick={()=>chooseMenu('auto-save')}>{autoSave?'✓ ':''}Auto Save</button><button onclick={()=>chooseMenu('revert')} disabled={!dirty}>Revert active file</button><div class="file-menu-separator"></div><button onclick={()=>chooseMenu('close')} disabled={!fileName}>Close editor <kbd>Ctrl+W</kbd></button><button onclick={()=>chooseMenu('close-all')} disabled={!tabs.length}>Close all editors</button><button onclick={()=>chooseMenu('open-vscode')} disabled={!workspace} title="Open the same project files in installed VS Code for Git, debugging and extensions">Open project in VS Code ↗</button><button onclick={()=>chooseMenu('close-workspace')} disabled={!workspace}>Close workspace</button>{:else if menu==='edit'}<button onclick={()=>editorAction('undo')} disabled={!editorActive}>Undo <kbd>Ctrl+Z</kbd></button><button onclick={()=>editorAction('redo')} disabled={!editorActive}>Redo <kbd>Ctrl+Y</kbd></button><div class="file-menu-separator"></div><button onclick={()=>editorAction('actions.find')} disabled={!editorActive}>Find <kbd>Ctrl+F</kbd></button><button onclick={()=>editorAction('editor.action.startFindReplaceAction')} disabled={!editorActive}>Replace <kbd>Ctrl+H</kbd></button><button onclick={()=>editorAction('editor.action.commentLine')} disabled={!editorActive}>Toggle line comment <kbd>Ctrl+/</kbd></button><button onclick={()=>editorAction('editor.action.formatDocument')} disabled={!formatSupported} title="Formatting providers: JavaScript, TypeScript, JSON, HTML and CSS">Format document <kbd>Shift+Alt+F</kbd></button>{:else if menu==='selection'}<button onclick={()=>editorAction('selectAll')} disabled={!editorActive}>Select all <kbd>Ctrl+A</kbd></button><button onclick={()=>editorAction('editor.action.addSelectionToNextFindMatch')} disabled={!editorActive}>Add next occurrence <kbd>Ctrl+D</kbd></button><button onclick={()=>editorAction('editor.action.insertCursorAbove')} disabled={!editorActive}>Add cursor above <kbd>Ctrl+Alt+↑</kbd></button><button onclick={()=>editorAction('editor.action.insertCursorBelow')} disabled={!editorActive}>Add cursor below <kbd>Ctrl+Alt+↓</kbd></button>{:else if menu==='go'}<button onclick={()=>chooseMenu('open')}>Go to file <kbd>Ctrl+P</kbd></button><button onclick={()=>{menuOpen=null;showPalette('line');}} disabled={!fileName}>Go to line <kbd>Ctrl+G</kbd></button><button onclick={()=>editorAction('editor.action.jumpToBracket')} disabled={!editorActive}>Go to bracket <kbd>Ctrl+Shift+\</kbd></button>{:else if menu==='view'}<button onclick={()=>chooseMenu('explorer')}>Toggle Explorer <kbd>Ctrl+B</kbd></button><button onclick={()=>chooseMenu('search')}>Search project <kbd>Ctrl+Shift+F</kbd></button><button onclick={()=>chooseMenu('assistant')}>Toggle Assistant <kbd>Ctrl+Alt+B</kbd></button><button onclick={()=>chooseMenu('output')}>Toggle output <kbd>Ctrl+J</kbd></button><button onclick={()=>editorAction('toggle-word-wrap')} disabled={!editorActive}>Toggle word wrap <kbd>Alt+Z</kbd></button><button onclick={()=>editorAction('toggle-minimap')} disabled={!editorActive}>Toggle minimap</button><button onclick={()=>chooseMenu('focus')}>{focusMode?'Exit':'Enter'} full screen</button>{:else if menu==='run'}<button onclick={()=>chooseMenu('run')} disabled={!runnable||busy}>Run active file <kbd>F5</kbd></button>{#if busy}<button onclick={()=>chooseMenu('stop')}>Stop task</button>{/if}{:else if menu==='terminal'}<button onclick={()=>chooseMenu('terminal')}>Focus terminal <kbd>Ctrl+`</kbd></button>{:else}<button onclick={()=>chooseMenu('shortcuts')}>Keyboard shortcuts</button>{/if}</div>{/if}</div>{/each}</nav>
  <span class="toolbar-divider"></span>
  <select class="workspace-picker" aria-label="Open coding workspace" value={workspace?.workspace_id||''} onchange={e=>void openWorkspace(e.currentTarget.value)} disabled={busy}><option value="">Local workspace</option>{#each workspaces as w}<option value={w.workspace_id}>{w.name}</option>{/each}</select>
  <button class="ide-shortcuts-button" onclick={()=>shortcutsOpen=true} title="Windows keyboard shortcuts">Shortcuts</button><span class="spacer"></span><span class="engine" class:ready={runtime?.sandbox.ready}><span class="engine-dot"></span>{runtime?.sandbox.ready?'Sandbox ready':'Sandbox offline'}</span>
