    <div class="search-options"><button aria-label="Match case" aria-pressed={searchCase} onclick={()=>searchCase=!searchCase}>Aa</button><button aria-label="Match whole word" aria-pressed={searchWord} onclick={()=>searchWord=!searchWord}>ab</button><button aria-label="Use regular expression" aria-pressed={searchRegex} onclick={()=>searchRegex=!searchRegex}>.*</button></div><p class="search-scope">Indexed contents: first 100 files · up to 200 matching lines. Unsaved edits are included.</p>{#if searchError}<p class="search-error" role="alert">{searchError}</p>{/if}
    <div class="search-results" aria-live="polite">{#if !workspace}<p>Open a workspace to search its files.</p>{:else if searchLoading}<p>Indexing project files…</p>{:else if !searchQuery.trim()}<p>Search file names and contents in this workspace.</p>{:else if !searchHits.length}<p>No matches for “{searchQuery}”.</p>{:else}<p>{searchHits.length} match{searchHits.length===1?'':'es'}</p>{#each searchHits as hit}<button class="search-hit" onclick={()=>void openSearchHit(hit)}><strong>{hit.name}{hit.line?`:${hit.line}`:''}</strong><span>{hit.preview}</span></button>{/each}{/if}</div>
   {:else if workspace}{#if tabs.length}<details class="open-editors" open><summary>Open editors <span>{tabs.length}</span></summary>{#each tabs as name}<div><button class:chosen={name===fileName} onclick={()=>void openFile(name)} title={name}>{name.split('/').pop()}{(name===fileName?dirty:drafts[name]!==saved[name])?' •':''}</button><button aria-label={'Close open editor '+name} onclick={()=>closeTab(name)}><X size={12}/></button></div>{/each}</details>{/if}<div class="explorer-tree-area" class:root-drop-target={rootDropTarget} ondragover={allowWorkspaceDrop} ondragleave={()=>rootDropTarget=false} ondrop={e=>void dropWorkspaceItem(e,'')} role="group" aria-label="Explorer file area" oncontextmenu={e=>{e.preventDefault();openFileMenu('','root',e.clientX,e.clientY);}}><WorkspaceTree files={workspace.files.map(f=>f.name)} folders={workspace.folders||[]} selected={fileName} cut={fileClipboard?.mode==='cut'?fileClipboard.path:''} onselect={openFile} oncontext={openFileMenu} ondrag={dragWorkspaceItem} ondrop={(e,folder)=>void dropWorkspaceItem(e,folder)} dragEnabled={!busy}/></div>{:else}<p class="empty-explorer">Import a folder or files to explore them here.</p>{/if}
  </aside>
  {/if}
  {#if showExplorer}<button type="button" class="side-resizer explorer-resizer" aria-label="Resize Explorer panel" title="Drag to resize Explorer" onpointerdown={e=>resizeSide('explorer',e)} onkeydown={e=>nudgeSide('explorer',e)}></button>{/if}
  <main class="editor-column">
   <div class="file-tabs">{#each tabs as name}<div class="tab-pair" draggable="true" ondragstart={e=>beginTabDrag(e,name)} ondragend={()=>{draggedTab='';tabDropTarget='';}} ondragover={e=>{if(e.dataTransfer?.types.includes('application/x-sovereign-editor-tab')){e.preventDefault();tabDropTarget=name;}}} ondragleave={()=>tabDropTarget=''} ondrop={e=>reorderTab(e,name)} class:tab-drop-target={tabDropTarget===name} class:active-tab={name===fileName} role="group" oncontextmenu={e=>showTabMenu(e,name)}><button class:active={name===fileName} onclick={()=>openFile(name)} title={name}>{name.split('/').pop()}{(name===fileName?dirty:drafts[name]!==saved[name])?' •':''}</button><button class="close-tab" aria-label={'Close '+name} onclick={()=>closeTab(name)}><X size={12}/></button></div>{/each}</div>
   <div class="editor-actions"><span>{workspace?.name||'Workspace'}{fileName?'  /  '+fileName:''}{dirty?'  •  Unsaved':''}</span><span class="spacer"></span>{#if task?.state==='completed'}<div class="change-summary-wrap"><button class="change-summary-pill" onclick={()=>showChangeSummary=!showChangeSummary} aria-expanded={showChangeSummary}>{task.changes?.filter(change=>!['mkdir','rmdir'].includes(change.action)).length||1} file{(task.changes?.filter(change=>!['mkdir','rmdir'].includes(change.action)).length||1)===1?'':'s'} changed <span class="added">+{changeCount.added}</span> <span class="removed">−{changeCount.removed}</span></button>{#if showChangeSummary}<div class="change-summary-popover"><strong>{task.changes?.map(change=>change.path).join(', ')||task.target}</strong><p><span class="added">+{changeCount.added} added</span> · <span class="removed">−{changeCount.removed} removed</span></p><button onclick={()=>{showChangeSummary=false;void reviewChanges();}}>Review changes</button><button onclick={acceptChanges}>Accept changes</button><button onclick={()=>{showChangeSummary=false;void undoChange();}}>Undo change</button></div>{/if}</div>{/if}{#if reviewing}<span>Inline review · added and removed lines</span><button onclick={acceptChanges} disabled={task?.state!=='completed'}>Accept</button><button onclick={()=>reviewing=false}>Edit file</button>{/if}<button onclick={()=>void saveFile()} disabled={!fileName||isAsset||reviewing} title="Save file (Ctrl+S)"><Save size={14}/>Save</button>{#if /\.(html?|md|markdown|txt|json|csv|svg)$/i.test(fileName)}<button onclick={()=>{reviewing=false;preview=!preview;}}>{preview?'Source':'Preview'}</button>{/if}<button class="run-action" onclick={runFile} disabled={!runnable||busy||reviewing||!runtime?.sandbox.ready}><Play size={14}/>Run</button></div>
   {#if saveConflict}<div class="save-conflict" role="alert"><span>Disk changes detected: {saveConflict.name}. Your edits are kept.</span><button onclick={()=>void compareConflict()}>Compare</button>{#if conflictReview}<button onclick={()=>void resolveConflict(true)}>Use disk version</button><button onclick={()=>void resolveConflict(false)}>Save my version</button><button onclick={()=>conflictReview=false}>Return to editor</button>{/if}</div>{/if}<div class="editor-area">{#if fileName}{#if isAsset&&imageAsset&&assetUrl}<ImagePreview src={assetUrl} name={fileName}/>{:else if isAsset}<div class="asset-preview">{#if imageAsset&&assetUrl}<img src={assetUrl} alt={fileName}/>{:else}<Files size={38}/><h3>{fileName.split('/').pop()}</h3><p>{assetFiles[fileName].binary?'Binary project asset':'File too large for the embedded text editor'}</p>{/if}<p>{(assetFiles[fileName].bytes/1024).toFixed(1)} KiB · Stored in your project folder</p>{#if assetUrl}<a href={assetUrl} download={fileName.split('/').pop()}>Download file</a>{/if}</div>{:else if conflictReview&&saveConflict?.name===fileName}<SourceDiff original={saveConflict.content} modified={fileContent} filename={fileName}/>{:else if reviewing && task && reviewPath===fileName}{#key reviewPath}<SourceDiff original={task.changes?.find(change=>change.path===fileName)?.before||task.original_content||''} modified={task.changes?.find(change=>change.path===fileName)?.after??fileContent} filename={fileName}/>{/key}{:else if preview&&svgFile&&svgUrl}<ImagePreview src={svgUrl} name={fileName}/>{:else if preview}<iframe title="File preview" sandbox="allow-scripts" srcdoc={previewDocument}></iframe>{:else}{#key (workspace?.workspace_id||'')+':'+fileName}<SourceEditor workspaceId={workspace?.workspace_id||''} bind:value={fileContent} filename={fileName} revealLine={searchLine} revealNonce={searchNonce} onmarkers={value=>markers=value} onsave={content=>void saveFile(content)}/>{/key}{/if}{:else}<div class="editor-empty"><FolderOpen size={38}/><h3>Your project, locally.</h3><p>Open a folder, import files, or create a source file.</p><p class="small">Python · JavaScript · TypeScript · Java · C/C++ · Go · Rust · PHP · Ruby</p></div>{/if}</div>
   {#if showOutput}
   <button type="button" class="panel-resizer" aria-label="Resize terminal. Drag or use arrow keys" onpointerdown={resizeTerminal} onkeydown={e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();terminalHeight=Math.max(130,Math.min(520,terminalHeight+(e.key==='ArrowUp'?20:-20)));localStorage.setItem('sovereign-terminal-height',String(terminalHeight));}}}><span></span></button>
   <section class="output-panel" style:height={`${terminalHeight}px`} aria-label="Code output"><div class="console-tabs"><button class:chosen={consoleTab==='terminal'} onclick={()=>consoleTab='terminal'}><Terminal size={13}/>Terminal</button><button class:chosen={consoleTab==='problems'} onclick={()=>consoleTab='problems'}>Problems {markers.length?markers.length:''}</button><button class:chosen={consoleTab==='changes'} onclick={()=>consoleTab='changes'}>Changes {task?.state==='completed'?'•':''}</button><span class="terminal-location" title={workspace?.host_path||''}>{terminalCwd||'project root'}</span>{#if workspace?.host_path}<button class="reveal-project" title={workspace.host_path} aria-label="Open project in File Explorer" onclick={()=>void revealProject()}><FolderOpen size={13}/></button>{/if}<span class="spacer"></span>{#if busy}<span class="running"><i></i>{stage} · {elapsed}s</span><button onclick={stopJob}>Stop</button>{:else}<button onclick={()=>output=''}>Clear</button>{/if}</div>{#if consoleTab==='changes'}<pre class="diff">{task?.diff||'No file changes were produced. The assistant did not apply an edit.'}</pre>{:else if consoleTab==='problems'}<div class="problems">{#if markers.length}{#each markers as marker}<p><span>{marker.severity>=8?'Error':'Warning'}</span> {fileName}:{marker.line} · {marker.message}</p>{/each}{:else}<p>No editor diagnostics for this file.</p>{/if}</div>{:else}<div class="terminal-surface" role="region" aria-label="Interactive terminal"><pre aria-live="polite">{output||'Terminal ready. Type a command here, or run the current file.'}</pre><form class="terminal-input" onsubmit={e=>{e.preventDefault();void submitTerminal();}}><span>{busy?'›':'$ /output/project'+(terminalCwd?'/'+terminalCwd:'')+'>'}</span><input aria-label="Terminal input" placeholder={busy&&jobKind==='agent'?'Assistant is working':busy&&jobKind==='edit'?'Assistant is editing':busy?'Type program input here…':'Type a shell command…'} disabled={busy&&(jobKind==='edit'||jobKind==='agent')} bind:value={terminalCommand} onkeydown={e=>{if(e.ctrlKey&&e.key==='c'&&busy){e.preventDefault();void stopJob();}if(!busy&&e.key==='ArrowUp'){e.preventDefault();historyPosition=Math.max(0,historyPosition-1);terminalCommand=commandHistory[historyPosition]||'';}if(!busy&&e.key==='ArrowDown'){e.preventDefault();historyPosition=Math.min(commandHistory.length,historyPosition+1);terminalCommand=commandHistory[historyPosition]||'';}}}/><button disabled={!terminalCommand.trim()||(busy&&(jobKind==='edit'||jobKind==='agent'))}>{busy?'Send':'Enter'}</button></form></div>{/if}</section>
   {/if}
  </main>
  {#if showAssistant}<button type="button" class="side-resizer assistant-resizer" aria-label="Resize Assistant panel" title="Drag to resize Assistant" onpointerdown={e=>resizeSide('assistant',e)} onkeydown={e=>nudgeSide('assistant',e)}></button>{/if}
  {#if showAssistant}
  <aside class="ai-panel">
   <div class="pane-title"><span><Sparkles size={15}/> ASSISTANT</span><span class="local-badge">LOCAL</span></div>
   <div class="ai-content">
    <div class="assistant-heading"><div class="assistant-heading-row"><h3>Ask about your project</h3><button class="new-coding-chat" onclick={newCodingChat} disabled={busy}>+ New chat</button></div><p>{workspace?.name||'Open or create a workspace'} · {workspace?.files.length||0} files</p><details class="safety-details"><summary>How changes are checked</summary><p class="small">The assistant reads the project tree, plans bounded file and folder changes, and validates the project in an isolated Docker sandbox before saving. You can switch files while it runs; edits made during validation cause a conflict instead of being overwritten.</p></details></div>
    <div class="coding-conversation" bind:this={codingConversation} onscroll={e=>stickToLatest=e.currentTarget.scrollHeight-e.currentTarget.clientHeight-e.currentTarget.scrollTop<80} aria-label="Coding task conversation">
     {#if !codingTurns.length && !task}<div class="coding-empty"><strong>Work across your project</strong><p>Ask the assistant to inspect the file tree, make changes, and check the result.</p><div><button onclick={()=>prompt='Find and fix errors in this project. Inspect the relevant files and run the available checks.'}>Find and fix errors</button><button onclick={()=>prompt='Create a new file for this feature. Inspect the project structure and place it in the appropriate folder.'}>Create a file</button></div></div>{/if}
     {#each codingTurns as turn (turn.jobId)}
      <div class="coding-turn"><p class="coding-request">{turn.instruction}</p><div class="coding-turn-status"><span>{turn.state==='running'?'Working on project':turn.state==='answered'?'Answered':turn.state==='completed'?'Changes applied':turn.state==='stopped'?'Stopped':'Check failed'}</span>{#if turn.taskId}<button onclick={()=>void openCodingTurn(turn)}>Review</button>{/if}</div>{#if turn.answer}<p class="coding-answer">{turn.answer}</p>{/if}<RouteDetails routing={turn.routing} compact /></div>
     {/each}
     {#if busy}<div class="agent-progress" role="status"><span class="running"><i></i>{stage}</span><small>{elapsed}s elapsed</small>{#each timeline.slice(-5) as event}<p>✓ {event.stage}</p>{/each}</div>{/if}
     {#if task && task.task_id!==acceptedTaskId}<div class="result" class:failed={task.state==='failed'}><strong>{task.state==='completed'?'✓ Changes applied — review and decide':task.state==='undone'?'Changes undone':'Check failed — originals kept'}</strong><span class="change-stats">{task.changes?.map(change=>change.path).join(', ')||task.target}</span><div class="review-actions"><button onclick={()=>void reviewChanges()}>Review</button>{#if task.state==='completed'}<button class="accept-change" onclick={acceptChanges}>Accept changes</button><button onclick={undoChange}>Undo</button>{/if}</div></div>{/if}
    </div>
    <div class="assistant-composer"><textarea aria-label="Coding task" bind:value={prompt} placeholder="Ask a question or describe a project change…" onkeydown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();void askAI();}}}></textarea><div class="assistant-actions"><span>Enter to send · Shift+Enter for a new line</span>{#if busy}<button class="composer-stop" onclick={stopJob}>Stop</button>{/if}<button class="primary" onclick={askAI} disabled={busy||!prompt.trim()}><Sparkles size={14}/>{busy?'Working…':'Send'}</button></div></div>
    {#if !runtime?.sandbox.ready}<DockerControl onready={()=>void refreshRuntime()}/>{/if}
   </div>
  </aside>
  {/if}
 </div>
 <footer role="status"><span>{notice}</span><span>{fileName.split('.').pop()?.toUpperCase()||'Workspace'} · UTF-8 · Local copy</span></footer>
</section>
