.editor-area{flex:1;min-height:320px;overflow:hidden}.editor-empty{height:100%;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:15px;color:var(--muted-foreground);padding:30px;text-align:center}.editor-empty h3{font-size:22px;color:var(--foreground)}.output-panel{height:245px;min-height:170px;display:flex;flex-direction:column;border-top:1px solid var(--border);overflow:auto}.output-panel pre{flex:1;min-height:70px;overflow:auto;padding:8px 12px;white-space:pre-wrap;font:12px/1.65 Consolas,monospace}.ai-panel{border-left:1px solid var(--border);overflow:auto}.ai-content{padding:14px;display:flex;flex-direction:column;gap:13px}.ai-content h3{font-size:17px;font-weight:600}.ai-content p{line-height:1.6;color:var(--muted-foreground)}.ai-content textarea{width:100%;min-height:120px;resize:vertical}.primary{justify-content:center;background:var(--primary);color:var(--primary-foreground);padding:9px}.small{font-size:11px}footer{display:flex;justify-content:space-between;gap:16px;border-top:1px solid var(--border);padding:5px 10px;font-size:10px;color:var(--muted-foreground)}footer span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}iframe{width:100%;height:100%;background:white;border:0}@media(max-width:1100px){.ide-body{grid-template-columns:165px minmax(220px,1fr)}.ai-panel{grid-column:1/-1;border-top:1px solid var(--border);max-height:300px}.ide{height:auto;min-height:800px}.editor-area{height:400px}}@media(max-width:650px){.ide-body{display:flex;flex-direction:column}.explorer{max-height:210px}.ide-toolbar{flex-wrap:wrap}.editor-area{min-height:380px}.ai-panel{max-height:none}.ide{height:auto}.output-panel{height:160px}}
.tab-pair{display:flex;align-items:center;border-right:1px solid var(--border)}.tab-pair>button{border:0}.tab-pair .close-tab{padding:5px;margin-right:5px}.console-tabs{display:flex;align-items:center;gap:9px;padding:5px 10px;border-bottom:1px solid var(--border)}.console-tabs button{font-size:11px;border-radius:0}.console-tabs .chosen{border-bottom:2px solid #76a9fa;color:var(--foreground)}.terminal-input{display:flex;align-items:center;gap:10px;padding:8px 14px;border-top:1px solid var(--border);font-family:Consolas,monospace}.terminal-input>span{color:#70c8a5}.terminal-input input{flex:1;background:transparent;border:0;outline:0;font:12px Consolas,monospace}.running{display:flex;align-items:center;gap:8px;font-size:11px}.running i{width:7px;height:7px;border-radius:50%;background:#91b9ff;animation:pulse 1.5s ease-in-out infinite}.agent-progress{border:1px solid var(--border);background:var(--muted);padding:12px;border-radius:8px}.agent-progress small{display:block;margin:8px 0;color:var(--muted-foreground)}.agent-progress p{font-size:11px}.assistant-heading{padding:10px 0}.local-badge{font-size:9px;border:1px solid var(--border);padding:2px 5px;border-radius:4px}.safety-details{font-size:11px;color:var(--muted-foreground)}.safety-details p{margin-top:10px}.ai-content .result{padding:12px;background:color-mix(in srgb,#57b78a 8%,transparent);border:1px solid color-mix(in srgb,#57b78a 30%,var(--border));border-radius:8px}.ide button{transition:background .15s ease,opacity .15s ease}.ide{animation:reveal .18s ease-out}@keyframes pulse{50%{opacity:.35}}@keyframes reveal{from{opacity:0;transform:translateY(3px)}to{opacity:1;transform:translateY(0)}}@media(prefers-reduced-motion:reduce){.ide,.running i{animation:none}.ide button{transition:none}}.ide-body.hide-explorer{grid-template-columns:minmax(240px,1fr) 300px}.ide-body.hide-assistant{grid-template-columns:200px minmax(240px,1fr)}.ide-body.hide-explorer.hide-assistant{grid-template-columns:minmax(240px,1fr)}.palette